<?php
require_once '../../includes/csrf.php';
declare(strict_types=1);
require_once __DIR__.'/auth.php'; requireLogin(); require_once dirname(__DIR__).'/api/wechat_pay.php';
function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
$error='';$saved=isset($_GET['saved']);$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();try{
    $action=(string)($_POST['action']??'save_config');
    if($action==='refund'){
        $number=preg_replace('/[^A-Z0-9]/','',(string)($_POST['order_no']??''));$order=DB::paymentOrder($number);
        if(!$order || $order['status']!=='SUCCESS')throw new RuntimeException('只有支付成功的订单可以退款');
        if(DB::refundForOrder($number))throw new RuntimeException('该订单已经发起过退款');
        $reason=trim(strip_tags((string)($_POST['reason']??'管理员全额退款')));$refundNo='TK'.date('YmdHis').strtoupper(bin2hex(random_bytes(4)));$pay=new WechatPay();$pay->assertReady();
        DB::createRefund($number,$refundNo,(int)$order['amount'],$reason,'PROCESSING');$result=$pay->refund($order,$refundNo,$reason);DB::updateRefund($refundNo,(string)($result['status']??'PROCESSING'),(string)($result['refund_id']??''));
        header('Location: payment.php?refund=1');exit;
    }elseif($action==='refresh_refund'){
        $number=preg_replace('/[^A-Z0-9]/','',(string)($_POST['order_no']??''));$refund=DB::refundForOrder($number);if(!$refund)throw new RuntimeException('未找到退款记录');
        $result=(new WechatPay())->queryRefund((string)$refund['out_refund_no']);DB::updateRefund((string)$refund['out_refund_no'],(string)($result['status']??$refund['status']),(string)($result['refund_id']??$refund['refund_id']));header('Location: payment.php?refreshed=1');exit;
    }else{
        foreach(['pay_enabled','pay_name','pay_appid','pay_mchid','pay_serial','pay_notify_url','pay_note'] as $field){$value=trim((string)($_POST[$field]??''));if($field==='pay_enabled')$value=$value==='1'?'1':'0';DB::setSetting($field,$value);}
        foreach(['pay_private_key','pay_api_v3_key'] as $field){$value=trim((string)($_POST[$field]??''));if($value!=='')DB::setSetting($field,WechatPay::encrypt($value));}
        header('Location: payment.php?saved=1');exit;
    }
}catch(Throwable $e){$error=$e->getMessage();}}
$v=fn(string $k,string $d='')=>DB::setting($k,$d);$orders=DB::paymentOrders();
