:root{--bg:#080c16;--card:#0d1320;--line:rgba(255,255,255,.1);--text:#e2e8f0;--muted:#94a3b8;--cyan:#38bdf8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}.wrap{max-width:1320px;margin:auto;padding:30px 20px}.top{display:flex;justify-content:space-between;gap:20px;align-items:center}.top a{color:var(--cyan);text-decoration:none}.sub{color:var(--muted)}.grid{display:grid;grid-template-columns:380px 1fr;gap:20px}.card{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:22px}label{display:block;color:var(--muted);font-size:.85rem;margin:14px 0 6px}input,textarea,select{width:100%;padding:10px;border:1px solid var(--line);border-radius:6px;background:#111827;color:var(--text);font:inherit}textarea{min-height:105px}.btn{margin-top:18px;border:0;border-radius:6px;background:#16a34a;color:#fff;padding:11px 18px;cursor:pointer}.notice{padding:10px 14px;border-radius:6px;margin:15px 0}.ok{background:#052e16;color:#86efac}.err{background:#451a1a;color:#fca5a5}table{width:100%;border-collapse:collapse;font-size:.82rem}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);white-space:nowrap}.status-SUCCESS,.refund-SUCCESS{color:#4ade80}.refund-PROCESSING{color:#fbbf24}.order-desc{max-width:180px}.action-form{display:flex;gap:6px;align-items:center}.action-form input{width:110px;padding:6px}.action-form button{border:0;border-radius:5px;padding:7px 9px;background:#dc2626;color:#fff;cursor:pointer;white-space:nowrap}.action-form button.refresh{background:#2563eb}@media(max-width:900px){.grid{grid-template-columns:1fr}.table-wrap{overflow:auto}}
