<?php if($saved):?><div class="notice ok">支付配置已保存</div><?php endif;?><?php if(isset($_GET['refund'])):?><div class="notice ok">退款申请已提交</div><?php endif;?><?php if(isset($_GET['refreshed'])):?><div class="notice ok">退款状态已刷新</div><?php endif;?><?php if($error):?><div class="notice err"><?=e($error)?></div><?php endif;?><div class="grid"><section class="card"><h2>微信支付配置</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="save_config"><label>启用状态</label><select name="pay_enabled"><option value="0" <?=$v('pay_enabled')!=='1'?'selected':''?>>停用</option><option value="1" <?=$v('pay_enabled')==='1'?'selected':''?>>启用</option></select><label>显示名称</label><input name="pay_name" value="<?=e($v('pay_name','微信支付'))?>" required><label>微信 AppID</label><input name="pay_appid" value="<?=e($v('pay_appid'))?>"><label>商户号 MCHID</label><input name="pay_mchid" value="<?=e($v('pay_mchid'))?>"><label>商户证书序列号</label><input name="pay_serial" value="<?=e($v('pay_serial'))?>"><label>商户 API 私钥</label><textarea name="pay_private_key" placeholder="已保存时留空表示不修改"></textarea><label>APIv3 Key</label><input type="password" name="pay_api_v3_key" placeholder="已保存时留空表示不修改"><label>支付回调地址</label><input type="url" name="pay_notify_url" value="<?=e($v('pay_notify_url'))?>" placeholder="https://域名/api/payment_notify.php"><label>备注</label><textarea name="pay_note"><?=e($v('pay_note'))?></textarea><button class="btn" type="submit">保存支付配置</button></form></section><section class="card"><h2>订单管理</h2><div class="table-wrap"><table><thead><tr><th>订单号</th><th>创建时间</th><th>付款内容</th><th>金额</th><th>支付状态</th><th>退款状态</th><th>操作</th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="7" class="sub">暂无订单</td></tr><?php else:foreach($orders as $o):$refund=$o['refund'];?><tr><td><?=e((string)$o['out_trade_no'])?></td><td><?=e((string)$o['created_at'])?></td><td class="order-desc"><?=e((string)$o['description'])?></td><td>¥<?=number_format((int)$o['amount']/100,2)?></td><td class="status-<?=e((string)$o['status'])?>"><?=e((string)$o['status'])?></td><td class="refund-<?=e((string)($refund['status']??''))?>"><?=e((string)($refund['status']??'未退款'))?></td><td><?php if($o['status']==='SUCCESS'&&!$refund):?><form class="action-form" method="post" onsubmit="return confirm('确定对该订单执行全额原路退款？此操作不可撤销。')"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="order_no" value="<?=e((string)$o['out_trade_no'])?>"><input name="reason" value="管理员全额退款" maxlength="80"><button type="submit">全额退款</button></form><?php elseif($refund&&$refund['status']!=='SUCCESS'):?><form class="action-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="refresh_refund"><input type="hidden" name="order_no" value="<?=e((string)$o['out_trade_no'])?>"><button class="refresh" type="submit">刷新状态</button></form><?php else:?>-<?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></div></body></html>
